import React, { useState } from 'react';
import CustomerList from './components/CustomerList';
import CustomerRegistrationForm from './components/CustomerRegistrationForm';
import CustomerDetails from './components/CustomerDetails';
import AboutPage from './components/AboutPage';
import Dashboard from './components/Dashboard';
import AgentList from './components/AgentList'; // <-- Added import for Agents
import './App.css';
import { SignedIn, SignedOut, SignInButton, UserButton } from '@clerk/clerk-react';
import { FaInfoCircle } from "react-icons/fa";

// ---- Home Page Component ----
function HomePage() {
  return (
    <div className="home-page-centerer">
      <div className="home-card pop-in">
        <div className="home-lock">
          <span role="img" aria-label="dashboard">📊</span>
        </div>
        <h2 className="home-title">Welcome to Your CRM Dashboard</h2>
        <p className="home-caption">
          Effortlessly manage, grow, and engage with your customers.<br />
          Enjoy modern analytics, interactive tracking, and fast onboarding.
        </p>
        <div className="home-feature-cards">
          <div className="feature-card slide-left">
            <span className="icon">👥</span>
            <h4>Customer Management</h4>
            <p>Store details, segment by type, and edit anytime.</p>
          </div>
          <div className="feature-card slide-up">
            <span className="icon">📝</span>
            <h4>Interaction Logging</h4>
            <p>Track purchases, inquiries, complaints, returns, and more—all in one place.</p>
          </div>
          <div className="feature-card slide-right">
            <span className="icon">📈</span>
            <h4>Analytics Ready</h4>
            <p>See business insights and optimize growth from day one.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

// ---- Main App Component ----
function App() {
  const [selectedCustomerId, setSelectedCustomerId] = useState(null);
  const [refreshList, setRefreshList] = useState(false);
  const [currentPage, setCurrentPage] = useState('home');

  return (
    <div className="app-container">
      <SignedIn>
        <header className="app-header">
          <span className="login-btn">
            <UserButton />
          </span>
          <h1 className="glitter-title">CRM System</h1>
          <nav className="nav-tabs">
            <button
              className={currentPage === 'home' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => { setCurrentPage('home'); setSelectedCustomerId(null); }}
            >
              Home
            </button>
            <button
              className={currentPage === 'dashboard' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => { setCurrentPage('dashboard'); setSelectedCustomerId(null); }}
            >
              Dashboard
            </button>
            <button
              className={currentPage === 'agents' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => { setCurrentPage('agents'); setSelectedCustomerId(null); }}
            >
              Agents
            </button>
            <button
              className={currentPage === 'customers' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => { setCurrentPage('customers'); setSelectedCustomerId(null); }}
            >
              Customers
            </button>
            <button
              className={currentPage === 'about' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => { setCurrentPage('about'); setSelectedCustomerId(null); }}
            >
              <FaInfoCircle style={{ marginRight: "6px", verticalAlign: "middle" }} /> About
            </button>
          </nav>
        </header>
        <main>
          {currentPage === 'home' ? (
            <HomePage />
          ) : currentPage === 'dashboard' ? (
            <Dashboard />
          ) : currentPage === 'agents' ? (
            <AgentList />
          ) : currentPage === 'customers' ? (
            !selectedCustomerId ? (
              <div className="crm-side-by-side">
                <div className="crm-left">
                  <CustomerRegistrationForm onCreate={() => setRefreshList(!refreshList)} />
                </div>
                <div className="crm-right">
                  <CustomerList key={refreshList} onSelect={setSelectedCustomerId} />
                </div>
              </div>
            ) : (
              <div className="content">
                <div className="form-container" style={{ width: '100%' }}>
                  <CustomerDetails
                    customerId={selectedCustomerId}
                    onBack={() => setSelectedCustomerId(null)}
                  />
                </div>
              </div>
            )
          ) : currentPage === 'about' ? (
            <AboutPage />
          ) : null}
        </main>
      </SignedIn>
      <SignedOut>
        <div className="login-center-container">
          <div className="glass-card">
            <div className="login-img-animated">
              <img
                src={process.env.PUBLIC_URL + "/profile.jpg"}
                alt="Login"
                className="login-img"
              />
            </div>
            <h1 className="login-title">CRM SYSTEM</h1>
            <h2>Welcome to CRM</h2>
            <SignInButton mode="modal">
              <button className="sign-in-btn">Sign In</button>
            </SignInButton>
          </div>
        </div>
      </SignedOut>
    </div>
  );
}

export default App;
